CREATE TABLE users(id uuid PRIMARY KEY, login text UNIQUE NOT NULL, display_name text NOT NULL, password_hash text, status text NOT NULL DEFAULT 'INVITED' CHECK(status IN ('INVITED','ACTIVE','BLOCKED')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE system_owner(singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton), user_id uuid UNIQUE NOT NULL REFERENCES users(id));
CREATE TABLE sessions(id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), token_hash text UNIQUE NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE activation_tokens(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE departments(id uuid PRIMARY KEY, name text UNIQUE NOT NULL, status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','ARCHIVED')));
CREATE TABLE department_memberships(id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), department_id uuid NOT NULL REFERENCES departments(id), valid_from timestamptz NOT NULL DEFAULT now(), valid_to timestamptz);
CREATE INDEX membership_department ON department_memberships(department_id,user_id);
CREATE UNIQUE INDEX active_membership ON department_memberships(user_id,department_id) WHERE valid_to IS NULL;
CREATE TABLE meetings(id uuid PRIMARY KEY, title text NOT NULL, description text NOT NULL DEFAULT '', status text NOT NULL CHECK(status IN ('DRAFT','SCHEDULED','OPEN','CLOSED','CANCELLED')), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, registration_open_at timestamptz NOT NULL, registration_close_at timestamptz NOT NULL, checkout_close_at timestamptz NOT NULL, latitude double precision NOT NULL CHECK(latitude BETWEEN -90 AND 90), longitude double precision NOT NULL CHECK(longitude BETWEEN -180 AND 180), radius_m integer NOT NULL DEFAULT 200 CHECK(radius_m=200), qr_version integer NOT NULL DEFAULT 1, created_by uuid NOT NULL REFERENCES users(id), timezone text NOT NULL DEFAULT 'Asia/Almaty', department_id uuid REFERENCES departments(id), location_label text NOT NULL DEFAULT '', late_after_minutes integer CHECK(late_after_minutes>=0), CHECK(ends_at>starts_at), CHECK(registration_close_at>registration_open_at), CHECK(checkout_close_at>=registration_close_at));
CREATE INDEX meetings_period ON meetings(starts_at);
CREATE INDEX meetings_department ON meetings(department_id);
CREATE TABLE meeting_attendees(meeting_id uuid NOT NULL REFERENCES meetings(id), user_id uuid NOT NULL REFERENCES users(id), required boolean NOT NULL DEFAULT true, department_id uuid REFERENCES departments(id), PRIMARY KEY(meeting_id,user_id));
CREATE INDEX attendees_user ON meeting_attendees(user_id);
CREATE TABLE permission_grants(id uuid PRIMARY KEY, grantee_id uuid NOT NULL REFERENCES users(id), permission text NOT NULL CHECK(permission IN ('users.manage','departments.manage','meetings.create','meetings.manage','meetings.qr.show','attendance.read','tasks.create','tasks.manage','tasks.review','feedback.read','feedback.manage','reports.export')), scope_type text NOT NULL CHECK(scope_type IN ('TEAM','DEPARTMENT','MEETING')), scope_id uuid, granted_by uuid NOT NULL REFERENCES users(id), revoked_at timestamptz, CHECK((scope_type='TEAM')=(scope_id IS NULL)));
CREATE INDEX grants_user ON permission_grants(grantee_id) WHERE revoked_at IS NULL;
CREATE TABLE attendance(id uuid PRIMARY KEY, meeting_id uuid NOT NULL REFERENCES meetings(id), user_id uuid NOT NULL REFERENCES users(id), check_in_at timestamptz NOT NULL, check_out_at timestamptz, check_in_distance_m double precision NOT NULL, check_out_distance_m double precision, check_in_accuracy double precision NOT NULL, check_out_accuracy double precision, UNIQUE(meeting_id,user_id), CHECK(check_out_at IS NULL OR check_out_at>=check_in_at));
CREATE INDEX attendance_user ON attendance(user_id,check_in_at);
CREATE TABLE geo_challenges(id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), meeting_id uuid NOT NULL REFERENCES meetings(id), action text NOT NULL CHECK(action IN ('check-in','check-out')), expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE tasks(id uuid PRIMARY KEY, department_id uuid REFERENCES departments(id), title text NOT NULL, description text NOT NULL DEFAULT '', assigned_to uuid NOT NULL REFERENCES users(id), due_at timestamptz NOT NULL, original_due_at timestamptz NOT NULL, priority text NOT NULL CHECK(priority IN ('LOW','NORMAL','HIGH')), status text NOT NULL DEFAULT 'TODO' CHECK(status IN ('TODO','IN_PROGRESS','IN_REVIEW','DONE')), created_by uuid NOT NULL REFERENCES users(id), accepted_at timestamptz, accepted_due_at timestamptz, expected_result text NOT NULL DEFAULT '');
CREATE INDEX tasks_assignee ON tasks(assigned_to);
CREATE INDEX tasks_due ON tasks(due_at);
CREATE INDEX tasks_department ON tasks(department_id);
CREATE TABLE task_collaborators(task_id uuid NOT NULL REFERENCES tasks(id), user_id uuid NOT NULL REFERENCES users(id), PRIMARY KEY(task_id,user_id));
CREATE TABLE task_comments(id uuid PRIMARY KEY, task_id uuid NOT NULL REFERENCES tasks(id), user_id uuid NOT NULL REFERENCES users(id), comment text NOT NULL, result_url text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE task_events(id uuid PRIMARY KEY, task_id uuid NOT NULL REFERENCES tasks(id), actor_id uuid NOT NULL REFERENCES users(id), event text NOT NULL, before_data jsonb, after_data jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE feedback(id uuid PRIMARY KEY, meeting_id uuid NOT NULL REFERENCES meetings(id), mode text NOT NULL CHECK(mode IN ('ANONYMOUS','NAMED')), author_user_id uuid REFERENCES users(id), rating integer CHECK(rating BETWEEN 1 AND 5), comment text NOT NULL, positive text, improvement text, coarse_date date NOT NULL, status text NOT NULL DEFAULT 'NEW' CHECK(status IN ('NEW','VIEWED','PROCESSED')), CHECK((mode='ANONYMOUS' AND author_user_id IS NULL) OR (mode='NAMED' AND author_user_id IS NOT NULL)));
CREATE INDEX feedback_meeting ON feedback(meeting_id);
CREATE TABLE feedback_notes(id uuid PRIMARY KEY, feedback_id uuid NOT NULL REFERENCES feedback(id), operator_id uuid NOT NULL REFERENCES users(id), note text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_log(id uuid PRIMARY KEY, actor_id uuid REFERENCES users(id), action text NOT NULL, object_type text NOT NULL, object_id uuid, before_data jsonb, after_data jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE rate_limits(key text PRIMARY KEY, count integer NOT NULL, expires_at timestamptz NOT NULL);
-- Anonymous dedup has only a client-generated random key, no user/session association.
CREATE TABLE feedback_dedup(key_hash text PRIMARY KEY, expires_at timestamptz NOT NULL);
